mapper.select:
select u.user_id, u.user_name, u.nick_name, u.status, u.dept_id, d.dept_name, (select count(*) from biz_query q where q.create_user_id = u.user_id) as query_count, (select count(*) from biz_survey s where s.create_user_id = u.user_id) as survey_count, (select count(*) from biz_query q where q.create_user_id = u.user_id and q.status = '1') as query_published, (select count(*) from biz_survey s where s.create_user_id = u.user_id and s.status = '1') as survey_published from sys_user u left join sys_dept d on d.dept_id = u.dept_id
u.del_flag = '0' and u.user_id = #{userId} and u.user_name like concat('%', #{userName}, '%') and u.nick_name like concat('%', #{nickName}, '%') and u.status = #{status} and u.dept_id = #{deptId}
order by (coalesce((select count(*) from biz_query q where q.create_user_id = u.user_id), 0) + coalesce((select count(*) from biz_survey s where s.create_user_id = u.user_id), 0)) desc, u.user_id asc
